class TupleCrossing(nn.Module):

    def __init__(self):
        super().__init__()
        self.fork = Fork()
        self.other = Fork()
        self.join = nn.Linear(8, 8)

    def forward(self, x, y):
        a, b = self.fork(x)
        c, d = self.other(y)
        e = self.join(a + d)
        return {'primary': e, 'skip': b + c}
